"""Build static pages; preview/noindex is the default. No network or third-party build service."""
import argparse, html, importlib.util, json, shutil
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
spec=importlib.util.spec_from_file_location('content',ROOT/'content/site.py')
c=importlib.util.module_from_spec(spec); spec.loader.exec_module(c)
e=lambda s:html.escape(str(s),quote=True)
DOMAIN='https://ferdant.com'; pages={}
arrow='<span aria-hidden="true">↗</span>'
def gp(g):return '/what-am-i-paying-for/guides/'+g['slug']+'/'
def button(url,text,secondary=False):return f'<a class="button{" secondary" if secondary else ""}" href="{e(url)}">{text}{arrow}</a>'
def cards():return ''.join(f'<a class="guide-card" href="{gp(g)}" data-search="{e(g["title"]+" "+g["description"]+" "+g["tag"])}"><div class="card-top"><span class="eyebrow">{g["tag"]}</span><span>Quick guide</span></div><h3>{g["title"]}</h3><p>{g["description"]}</p><span class="text-link">Read the guide {arrow}</span></a>' for g in c.GUIDES)
def topics():return ''.join(f'<a class="topic-row" href="/{b["slug"]}/"><span class="topic-number">0{i+1}</span><span class="topic-copy"><strong>{b["name"]}</strong><span>{b["label"]}</span></span><p>{b["description"]}</p>{arrow}</a>' for i,b in enumerate(c.BRANCHES))
def page(path,title,description,body,crumbs=None):
 schema=[{'@context':'https://schema.org','@type':'WebSite','name':'Ferdant','url':DOMAIN+'/'},{'@context':'https://schema.org','@type':'WebPage','name':title,'description':description,'url':DOMAIN+path,'inLanguage':'en'}]
 crumb=''
 if crumbs:
  schema.append({'@context':'https://schema.org','@type':'BreadcrumbList','itemListElement':[{'@type':'ListItem','position':i+1,'name':n,'item':DOMAIN+u} for i,(n,u) in enumerate(crumbs)]})
  crumb='<nav class="breadcrumbs" aria-label="Breadcrumb">'+''.join(f'<a href="{u}">{e(n)}</a><span aria-hidden="true">/</span>' for n,u in crumbs[:-1])+f'<span>{e(crumbs[-1][0])}</span></nav>'
 preview='<div class="preview-note">Editorial preview · Public launch review pending</div>' if args.mode=='preview' else ''
 robots='noindex,follow' if args.mode=='preview' or path=='/404.html' else 'index,follow'
 pages[path]=f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{e(title)} | Ferdant</title><meta name="description" content="{e(description)}"><meta name="robots" content="{robots}"><meta name="theme-color" content="#f8f9f6"><link rel="canonical" href="{DOMAIN}{path}"><link rel="icon" href="/assets/mark.svg" type="image/svg+xml"><link rel="stylesheet" href="/styles.css"><meta property="og:type" content="website"><meta property="og:title" content="{e(title)} | Ferdant"><meta property="og:description" content="{e(description)}"><meta property="og:url" content="{DOMAIN}{path}"><meta property="og:site_name" content="Ferdant"><script type="application/ld+json">{json.dumps(schema,ensure_ascii=False)}</script><script src="/site.js" defer></script></head>
<body><a class="skip" href="#main">Skip to content</a>{preview}<div class="page"><header class="site-header"><a class="wordmark" href="/" aria-label="Ferdant home">ferdant<span>.</span></a><nav class="desktop-nav" aria-label="Main navigation"><a href="/#communities">Five topics</a><a href="/guides/">The guides</a><a href="/about/">Our approach</a></nav><a class="header-link" href="/#communities">Find your community {arrow}</a><details class="mobile-menu"><summary>Menu</summary><nav aria-label="Mobile navigation"><a href="/#communities">Five topics</a><a href="/guides/">The guides</a><a href="/about/">Our approach</a></nav></details></header><main id="main" tabindex="-1">{crumb}{body}</main><footer class="site-footer"><div><a class="wordmark" href="/">ferdant<span>.</span></a><p>Useful information.<br>A place to take it further.</p></div><nav aria-label="Footer navigation"><a href="/guides/">Guides</a><a href="/about/">About Ferdant</a><a href="/sources-and-corrections/">Sources & corrections</a><a href="/privacy/">Privacy</a></nav><p class="footer-note">Five practical-help communities.<br>Personal account details belong in private.</p></footer></div></body></html>'''
def home():
 page('/','Practical guides for everyday problems','Clear guides and five communities for connectivity, repairs, utilities, bills, paperwork and preparedness. Find a useful next step with Ferdant.',f'''<section class="hero"><div class="hero-copy"><p class="eyebrow">A little clarity goes a long way</p><h1>Make sense of<br>the <em>everyday.</em></h1><p class="hero-deck">The bill you can’t explain. The repair you can’t quite describe. The next step you haven’t found.</p><p class="hero-detail">Practical guides, useful sources and five communities to help you ask a clearer question.</p><div class="hero-actions">{button('/guides/','Find a useful guide')}{button('#communities','Explore the communities',True)}</div></div><div class="hero-art" aria-hidden="true"><span class="art-caption">A place for useful things</span><img src="/assets/porcelain.svg" width="460" height="460" alt=""><div class="art-bottom"><span>Considered.<br>Useful. Connected.</span><span class="small-seal">f.</span></div></div></section><div class="principle-strip"><span>Start with the question.</span><span>Check the source.</span><span>Share what helped.</span></div><section class="section"><div class="section-heading"><div><p class="eyebrow">The first pages of the library</p><h2>A clearer next step.</h2></div><p>Start with bills and paperwork.<br>Read a guide, then take the question further.</p></div><div class="guide-grid">{cards()}</div><a class="inline-link" href="/guides/">Browse the guide library {arrow}</a></section><section class="section topics" id="communities"><div class="section-heading"><div><p class="eyebrow">Five ways in</p><h2>What are you working through?</h2></div><p>Each topic has its own community.<br>Choose the one closest to your question.</p></div><nav aria-label="The five communities">{topics()}</nav></section><section class="approach-band"><p class="eyebrow">Useful before you join</p><h2>Read the answer.<br>Keep the conversation going.</h2><div><p>You can use every guide without an account. When a question needs more context, the relevant Reddit community is a place to compare experiences and share an update.</p><a class="inline-link" href="/about/">How Ferdant works {arrow}</a></div></section>''')
def hubs():
 for b in c.BRANCHES:
  questions=''.join(f'<li>{e(q)}</li>' for q in b['questions']); bring=''.join(f'<li>{e(q)}</li>' for q in b['bring']); name,url,desc=b['resource']
  guides=f'<section class="section"><p class="eyebrow">From this topic</p><h2>Start with a guide.</h2><div class="guide-grid">{cards()}</div></section>' if b['name']=='WhatAmIPayingFor' else ''
  page('/'+b['slug']+'/',b['label']+' help — '+b['name'],b['description'],f'''<section class="page-intro"><p class="eyebrow">{b['name']} · {b['label']}</p><h1>{b['title']}</h1><p class="deck">{b['description']}</p>{button('https://www.reddit.com/r/'+b['name']+'/', 'Visit r/'+b['name'])}</section><section class="two-column section"><div><p class="eyebrow">A useful starting point</p><h2>Bring the question into focus.</h2><ul class="question-list">{questions}</ul></div><div class="note-panel"><h3>Before you ask</h3><ul>{bring}</ul><p>{b['boundary']}</p></div></section>{guides}<section class="resource-band"><div><p class="eyebrow">An existing resource</p><h2>{name}</h2><p>{desc}</p></div>{button(url,'Open the resource',True)}</section><section class="section cross-topics"><h2>Does your question cross topics?</h2><p>A service problem can also be a billing problem. Choose the community that fits the step you need help with.</p><a class="inline-link" href="/#communities">See all five communities {arrow}</a></section>''',[('Home','/'),(b['name'],'/'+b['slug']+'/')])
def tool(g):
 if g['tool']=='bill':return '''<section class="interactive" id="quick-tool"><p class="eyebrow">A small working tool</p><h2>Put a number on the change.</h2><p>Compare totals for the same period, in the same currency. This shows the difference, not the reason or whether the charge is correct.</p><form id="bill-comparison"><div class="input-pair"><label>Previous bill ($)<input name="previous" type="number" inputmode="decimal" min="0" step="0.01" required placeholder="e.g. 60"></label><label>Current bill ($)<input name="current" type="number" inputmode="decimal" min="0" step="0.01" required placeholder="e.g. 75"></label></div><button class="button" type="submit">Compare the totals <span aria-hidden="true">→</span></button></form><p class="tool-result" id="bill-result" role="status" aria-live="polite">Enter two totals to compare.</p><p class="fine-print">Calculated in this page. Nothing is sent or saved. Without JavaScript, subtract the previous total from the current total.</p></section>'''
 if g['tool']=='checklist':return '''<section class="interactive" id="quick-tool"><p class="eyebrow">Your private check</p><h2>Have you kept the essentials?</h2><div class="checklist"><label><input type="checkbox"> I know which account or business bills me.</label><label><input type="checkbox"> I saved the request and any confirmation.</label><label><input type="checkbox"> I recorded the stated end or renewal date.</label><label><input type="checkbox"> I know where to check the next charge.</label></div><p class="fine-print">A working checklist, not a record of cancellation. Checks reset when you reload.</p></section>'''
 return ''
def guides():
 page('/guides/','Practical guides for bills and paperwork','Browse source-linked guides to understanding a changed bill, canceling subscriptions and writing a clear billing question.',f'''<section class="page-intro"><p class="eyebrow">The Ferdant library</p><h1>A question.<br>A useful next step.</h1><p class="deck">Small, practical guides you can use before asking for help. The library begins with bills, subscriptions and paperwork.</p></section><section class="library section"><div class="search-row" data-search-controls hidden><label for="guide-search">Find a guide</label><input id="guide-search" type="search" placeholder="Try “bill”, “cancel” or “paperwork”" autocomplete="off"><p id="search-status" role="status" aria-live="polite">3 guides</p></div><div class="guide-grid">{cards()}</div><p id="no-results" hidden>No matching guides yet. Try another word or <a href="/#communities">find the relevant community</a>.</p></section>''',[('Home','/'),('Guides','/guides/')])
 for g in c.GUIDES:
  sections=''.join(f'<details class="guide-step" id="step-{i+1}"><summary><span class="step-number">0{i+1}</span><strong>{e(t)}</strong><span class="step-toggle" aria-hidden="true">+</span></summary><div class="step-detail"><p>{e(p)}</p></div></details>' for i,(t,p) in enumerate(g['sections']))
  quick='<ol>'+''.join(f'<li>{e(item)}</li>' for item in g['quick'])+'</ol>'; next_id='quick-tool' if g['tool'] in ['bill','checklist'] else 'message-template'; next_label='Compare your bills' if g['tool']=='bill' else 'Use the quick checklist' if g['tool']=='checklist' else 'Copy a starting point'
  sources=''.join(f'<li><a href="{e(url)}">{e(n)} {arrow}</a><span>{e(d)} · Checked November 2, 2026</span></li>' for n,url,d in g['sources'])
  related=''.join(f'<a href="{gp(x)}">{x["title"]} {arrow}</a>' for x in c.GUIDES if x!=g)
  page(gp(g),g['title'],g['description'],f'''<article><header class="article-intro"><p class="eyebrow">WhatAmIPayingFor · {g['tag']} · Quick guide</p><h1>{g['title']}</h1><p class="deck">{g['deck']}</p><p class="review-date">Prepared from public guidance · Source check: November 2, 2026</p></header><div class="article-layout"><div class="prose"><section class="quick-answer" aria-labelledby="quick-answer-title"><p class="eyebrow">Start here</p><h2 id="quick-answer-title">The short answer.</h2><p class="article-answer">{g['intro']}</p>{quick}{button("#"+next_id,next_label)}<p class="quick-note">{g['briefNote']}</p></section>{tool(g)}<section class="template"><p class="eyebrow">Make it your own</p><h2>A starting point for your message.</h2><p>Adapt this example privately. Use the business’s verified support channel for account-specific details.</p><blockquote id="message-template">{e(g['template'])}</blockquote><button class="copy-button" data-copy="message-template" hidden>Copy the starting point</button><p class="copy-status" role="status"></p></section><section class="extra-detail"><h2>More detail, if you need it.</h2>{sections}</section><details id="sources" class="sources"><summary>Sources & scope</summary><div class="source-detail"><p>{g['scope']}</p><ul>{sources}</ul><p>A source check is not a review by the agencies or a claim of professional expertise. <a href="/sources-and-corrections/">Source and correction policy.</a></p></div></details><section class="community-followup"><h2>Still working through it?</h2><p>Ask a specific question or share an update. Remove account numbers, addresses, case identifiers and other people’s details before posting.</p>{button('https://www.reddit.com/r/WhatAmIPayingFor/','Go to WhatAmIPayingFor')}</section><nav class="related" aria-label="Related guides"><p class="eyebrow">Keep reading</p>{related}</nav></div></div></article>''',[('Home','/'),('WhatAmIPayingFor','/what-am-i-paying-for/'),(g['title'],gp(g))])
def info(path,title,deck,body):page(path,title,title+' — Ferdant practical-help communities.',f'<section class="page-intro"><p class="eyebrow">Ferdant</p><h1>{title}</h1><p class="deck">{deck}</p></section><div class="reading-page prose">{body}</div>',[('Home','/'),(title,path)])
def information():
 info('/about/','Useful information. Room for a conversation.','Ferdant brings five practical-help communities into one place. Each has its own topic, its own questions and its own conversation.','''<h2>Start with something you can use.</h2><p>A guide should help you understand a problem, organize what you know and find the next responsible person or source. You can read every page without joining a community.</p><h2>Keep the full problem in view.</h2><p>Connectivity includes providers and installation. Repair includes specialist services and follow-up. Utilities includes energy, water and continuity. Money includes contracts, forms and administration. Preparedness includes practical planning and recovery.</p><h2>Be clear about what is known.</h2><p>We link public guidance and show when we checked it. A community experience can help without establishing what will happen in your situation. Pages should make that distinction visible.</p><h2>A place to ask, not a promise of service.</h2><p>The communities support peer discussion. A reply, professional referral, correction or response time is not guaranteed. Account decisions remain with the responsible organization.</p><h2>A separate campus purpose.</h2><p>AggieBillHelp is the separate UC Davis campus community for student money and paperwork questions. It is not the name or scope of all five Ferdant branches. These pages do not imply a university affiliation or official campus service.</p><a class="inline-link" href="/#communities">Explore the five communities ↗</a>''')
 correction=''.join(f'<li><a href="https://www.reddit.com/message/compose/?to=%2Fr%2F{b["name"]}">{b["name"]} moderator mail ↗</a></li>' for b in c.BRANCHES)
 info('/sources-and-corrections/','Sources matter. So do corrections.','A useful guide makes it easy to check a claim and flag what needs another look.',f'''<h2>What the dates mean</h2><p>We link the original publisher where possible. The publisher’s date and our source-check date are different: a recent check does not make an older source newly published. Missing source dates remain explicit.</p><h2>What these pages can support</h2><p>These are original practical summaries and working tools, not a republished archive of community conversations. A Reddit score is not proof of demand, and a reported result is not automatically independently verified. Calculations state their assumptions.</p><h2>Suggest a correction</h2><p>Send the page URL, exact statement, reason it may be wrong and a supporting public source to the relevant community’s moderator mail. Do not include private documents or account access. Reddit may require sign-in. Review timing is not promised.</p><ul>{correction}</ul><h2>Check what applies</h2><p>Check the source, location and service before relying on a page. Material corrections should record what changed and when. This first preview has no published correction history yet.</p>''')
 info('/privacy/','Use a guide. Keep your records.','You do not need an account to read these pages.','''<h2>Tools work in your browser</h2><p>Search terms, bill totals and checklist selections are used in the open page only. This site does not send them to a server, save them to local storage or set tracking cookies. Refreshing clears the tools. Copying a template uses your clipboard only after you press the copy button.</p><h2>Hosting and outside links</h2><p>The public site uses GitHub Pages. Hosting providers may process technical request information. See <a href="https://docs.github.com/en/site-policy/privacy-policies/github-general-privacy-statement">GitHub’s privacy statement</a>. Reddit and agency links lead to services with their own policies.</p><h2>No document uploads</h2><p>There is no upload form here. Keep identity documents, account numbers, credentials and case records out of public discussions. Use a verified private process when the task requires those details.</p>''')
 page('/404.html','Page not found','Return to Ferdant’s guide library and five communities.',f'<section class="page-intro"><p class="eyebrow">404 · A wrong turn</p><h1>This page isn’t here.</h1><p class="deck">The link may have changed. Start with the library or choose the topic closest to your question.</p>{button("/guides/","Go to the guides")}</section>')
if __name__=='__main__':
 p=argparse.ArgumentParser();p.add_argument('--mode',choices=['preview','production'],default='preview');p.add_argument('--output',type=Path,default=ROOT);args=p.parse_args()
 home();hubs();guides();information()
 for path,doc in pages.items():
  target=args.output/(path.lstrip('/') if path.endswith('.html') else path.lstrip('/')+'index.html');target.parent.mkdir(parents=True,exist_ok=True);target.write_text(doc,encoding='utf-8')
 (args.output/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join(f'<url><loc>{DOMAIN}{u}</loc></url>' for u in pages if u!='/404.html')+'</urlset>\n',encoding='utf-8')
 (args.output/'robots.txt').write_text('User-agent: *\nAllow: /\n'+('Sitemap: '+DOMAIN+'/sitemap.xml\n' if args.mode=='production' else '# Preview pages carry noindex; allow crawlers to see it.\n'),encoding='utf-8')
 if args.output.resolve()!=ROOT:
  for name in ['styles.css','site.js','CNAME','.nojekyll']:
   shutil.copy2(ROOT/name,args.output/name)
  shutil.copytree(ROOT/'assets',args.output/'assets',dirs_exist_ok=True)
  for name in ['integrations','config']:
   shutil.copytree(ROOT/name,args.output/name,dirs_exist_ok=True)
 print(f'Built {len(pages)} static pages in {args.mode} mode at {args.output}')
